<?php require __DIR__.'/../bootstrap.php';require_login();if(plan_limit_reached('tasks')){flash('error','Your current plan limit has been reached. Upgrade to continue.');redirect('/pricing/');}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();db()->prepare("INSERT INTO tasks(user_id,title,description,status,priority,due_date,created_at,updated_at) VALUES(?,?,?,?,?,?,NOW(),NOW())")->execute([current_user()['id'],post('title'),post('description'),post('status','Todo'),post('priority','Medium'),post('due_date')?:null]);increment_counter('tasks_created_counter'); log_event('tasks_created',(int)current_user()['id']); redirect('/tasks/');}$title='New Task';require __DIR__.'/../includes/header.php';?><form class="card form-card" method="post"><?=csrf_field()?><label>Title<input name="title" required></label><label>Description<textarea name="description" rows="6"></textarea></label><div class="grid2"><label>Status<select name="status"><option>Todo</option><option>In Progress</option><option>Completed</option></select></label><label>Priority<select name="priority"><option>Medium</option><option>High</option><option>Low</option></select></label><label>Due Date<input type="date" name="due_date"></label></div><button class="btn">Create Task</button><p><a class="btn secondary small" href="/ai/?prompt=Task%20assist%3A%20help%20me%20improve%20this%20task">✨ AI Assist</a></p></form><?php require __DIR__.'/../includes/footer.php'; ?>